function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const B64 = '';
const UPD = JSON.parse(typeof Buffer !== 'undefined' ? Buffer.from(B64, 'base64').toString('utf8') : decodeURIComponent(escape(atob(B64))));
const hdr = (($('GET INV header').first().json.values || [[]])[0] || []).map(s);
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 200) { throw new Error('ABORT: INVESTORS only ' + rows.length + ' rows'); }
const COL = {}; for (const h of ['sector', 'stage', 'cheque_inr_cr']) { const i = hdr.indexOf(h); if (i < 0) { throw new Error('ABORT: INVESTORS column missing ' + h); } COL[h] = colLetter(i); }
const byName = {}; for (const r of rows) { const k = nz(r.investor); if (k) { (byName[k] = byName[k] || []).push(r); } }
const NOTE = /meeting|deals shared|she say/i;
const data = [], log = [], notFound = [], kept = [];
for (const name of Object.keys(UPD)) {
  const rs = byName[nz(name)] || [];
  if (!rs.length) { notFound.push(name); continue; }
  const u = UPD[name]; const stageOnly = Object.keys(u).length === 1 && u.stage;
  for (const r of rs) { for (const f of Object.keys(u)) {
    const cur = s(r[f]);
    // stage-only fills never overwrite a real stage someone has typed since the audit
    if (stageOnly && cur && !NOTE.test(cur)) { kept.push(name + ' (row ' + r.row_number + ') stage kept: ' + cur.slice(0, 40)); continue; }
    if (cur === u[f]) { continue; }
    data.push({ range: 'INVESTORS!' + COL[f] + r.row_number, values: [[u[f]]] });
    log.push({ investor: name, row: r.row_number, field: f, before: cur, after: u[f] });
  } }
}
if (notFound.length > 3) { throw new Error('ABORT: names not found in INVESTORS: ' + notFound.join(', ')); }
if (!data.length) { throw new Error('ABORT: nothing to write'); }
if (data.length > 200) { throw new Error('ABORT: ' + data.length + ' writes exceeds guard'); }
return [{ json: { writes: data.length, investors: new Set(log.map(function (l) { return l.investor; })).size, data: data, log: log, notFound: notFound, kept: kept } }];

function s(v) { return String(v == null ? '' : v).trim(); }
const plan = $('Plan INV').first().json;
const after = $input.all().map(function (i) { return i.json; });
const byRow = {}; for (const r of after) { byRow[r.row_number] = r; }
const bad = plan.log.filter(function (l) { return s((byRow[l.row] || {})[l.field]) !== l.after; }).map(function (l) { return l.investor + '.' + l.field; });
return [{ json: { rows_after: after.length, writes: plan.writes, investors_changed: plan.investors, not_applied: bad, not_found: plan.notFound, kept_existing_stage: plan.kept, ok: bad.length === 0 } }];
